 "content": "def transform(grid):
    """Repeat the non-first-column pattern across each band, using its seed color."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid)
                if row and row[0] != 0 and all(v == row[0] for v in row)]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    row_ranges = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_ranges = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]

    # The pattern is the sole nonempty interior tile outside the seed column.
    pattern = None
    for br, (r0, r1) in enumerate(row_ranges):
        for bc, (c0, c1) in enumerate(col_ranges):
            if bc == 0:
                continue
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0]
            if cells:
                pattern = (r1-r0, c1-c0, [(dr, dc) for dr, dc, _ in cells])
                break
        if pattern is not None:
            break
    if pattern is None:
        return [row[:] for row in grid]
    ph, pw, mask = pattern

    out = [row[:] for row in grid]
    for r0, r1 in row_ranges:
        c0, c1 = col_ranges[0]
        colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
        if not colors:
            continue
        # Seed color is the most frequent non-background color in the first tile.
        color = max(set(colors), key=colors.count)
        for tc0, tc1 in col_ranges:
            for r in range(r0, r1):
                for c in range(tc0, tc1):
                    out[r][c] = 0
            for dr, dc in mask:
                rr, cc = r0 + dr, tc0 + dc
                if rr < r1 and cc < tc1:
                    out[rr][cc] = color
    return out
